import { ToolbarPlacement } from '../../../types/toolbar.js';

/**
 * Gets toolbar top and right position with a given placement and a given boundaries
 *
 * @param placement -
 * @param maxBoundaries -
 */
export function getToolbarPlacement(
  placement: ToolbarPlacement,
  maxBoundaries: {
    top: number;
    right: number;
  },
) {
  switch (placement) {
    case 'top-right': {
      return { top: 0, right: 0 };
    }
    case 'bottom-right': {
      return { top: maxBoundaries.top, right: 0 };
    }
    case 'bottom-left': {
      return { top: maxBoundaries.top, right: maxBoundaries.right };
    }
    case 'top-left': {
      return { top: 0, right: maxBoundaries.right };
    }
    default: {
      return { top: 0, right: 0 };
    }
  }
}
